template:
try {
{{#corpo}}
} catch ({{erro}}) {
    console.log({{erro}})
    let lineError = '0';
    let fileName = '0';
    const stackFrames = ErrorStackParser.parse({{erro}});
    if (stackFrames.length > 0) {
        lineError = stackFrames[0].lineNumber;
        fileName = stackFrames[0].fileName;
    }
    logExeption({ descricaoDoErro: {{descricao}}, linhaDoErro: lineError, nomeDoArquivo: fileName, data_criacao: dateNow(), data_atualizacao: dateNow(), deletado: false })
    return { status: false, msg: 'Erro interno do servidor, log gerado' }
}
